using Captovix;
int n=0;void Check(bool v,string m){if(!v)throw new Exception(m);n++;}
const int w=103,h=137;var original=new byte[w*600*4];new Random(125).NextBytes(original);ScrollFrame Frame(int offset){var b=new byte[w*h*4];Buffer.BlockCopy(original,offset*w*4,b,0,b.Length);return new(w,h,b);}
foreach(int shift in new[]{1,2,13,27,46,70,93,110}){var a=Frame(0);var b=Frame(shift);var m=ScrollStitching.Match(a,b);Check(m.Kind==ScrollMatchKind.Matched&&m.Overlap==h-shift,"Exact shift");var output=ScrollStitching.Compose(w,h,[m.Overlap],i=>i==0?a:b);Check(output.SequenceEqual(original.Take(output.Length)),"No missing/duplicate rows");}
var sparseRows=Enumerable.Range(0,24).Select(i=>(int)((i+.5)*h/24)).ToHashSet();var denseRows=Enumerable.Range(0,96).Select(i=>(int)((i+.5)*h/96));int row=denseRows.First(y=>!sparseRows.Contains(y));var first=Frame(0);var changed=first.Pixels.ToArray();for(int x=0;x<w;x++)for(int c=0;c<3;c++)changed[(row*w+x)*4+c]=(byte)(255-first.Pixels[(row*w+x)*4+c]);Check(ScrollStitching.Match(first,new(w,h,changed)).Kind!=ScrollMatchKind.Duplicate,"Changed row missed by old sparse sample cannot be called duplicate");
var tiny=first.Pixels.ToArray();tiny[0]^=1;Check(ScrollStitching.Match(first,new(w,h,tiny)).Kind!=ScrollMatchKind.Duplicate,"Even one changed pixel must not be discarded as duplicate");
var transposed=AdvancedScroll.Transpose(first);Check(AdvancedScroll.Transpose(transposed).Pixels.SequenceEqual(first.Pixels),"Horizontal transpose exact");var trimmed=AdvancedScroll.Trim(transposed,9,11);Check(trimmed.Height==transposed.Height-20&&trimmed.Pixels.SequenceEqual(transposed.Pixels.Skip(9*transposed.Width*4).Take(trimmed.Pixels.Length)),"Horizontal fixed edges trim exact columns");
using var cancel=new CancellationTokenSource();cancel.Cancel();try{ScrollStitching.Match(first,first,cancel.Token);throw new Exception("Cancellation ignored");}catch(OperationCanceledException){n++;}Console.WriteLine($"{n} scrolling quality checks passed.");

Check(ScrollQuality.Settled(first,first),"Stationary pixels accepted");var moving=first.Pixels.ToArray();for(int y=20;y<55;y++)for(int x=20;x<50;x++)for(int c=0;c<3;c++)moving[(y*w+x)*4+c]^=255;Check(!ScrollQuality.Settled(first,new(w,h,moving)),"Small moving panel is not diluted by large background");
var repeated=new ScrollFrame(96,120,Enumerable.Repeat((byte)200,96*120*4).ToArray());Check(ScrollStitching.Match(repeated,repeated).Kind==ScrollMatchKind.Duplicate,"Blank duplicate is never appended");
const int fw=96,fh=180,header=18,footer=12,advance=47;var body=new byte[fw*600*4];new Random(703).NextBytes(body);
ScrollFrame WithFixed(int start){var data=new byte[fw*fh*4];Buffer.BlockCopy(body,start*fw*4,data,header*fw*4,(fh-header-footer)*fw*4);for(int y=0;y<fh;y++)if(y<header||y>=fh-footer)for(int x=0;x<fw;x++)for(int c=0;c<4;c++)data[(y*fw+x)*4+c]=(byte)((x*13+y*7+c)%256);return new(fw,fh,data);}
var fixedA=WithFixed(0);var fixedB=WithFixed(advance);var bands=ScrollQuality.FixedBands(fixedA,fixedB);Check(bands==(header,footer),"Detect exact fixed header and footer without scanning entire page");var ta=AdvancedScroll.Trim(fixedA,bands.Header,bands.Footer);var tb=AdvancedScroll.Trim(fixedB,bands.Header,bands.Footer);var joined=ScrollStitching.Match(ta,tb);Check(joined.Kind==ScrollMatchKind.Matched&&joined.Overlap==ta.Height-advance,"Trimmed fixed bands retain precise content offset");Check(ScrollStitching.Compose(fw,ta.Height,[joined.Overlap],i=>i==0?ta:tb).SequenceEqual(body.Take((ta.Height+advance)*fw*4)),"Fixed headers do not cause missing or repeated body rows");
var drift=Frame(37);var driftPixels=new byte[drift.Pixels.Length];for(int y=0;y<h;y++)for(int x=3;x<w;x++)Buffer.BlockCopy(drift.Pixels,(y*w+x-3)*4,driftPixels,(y*w+x)*4,4);Check(ScrollStitching.Match(first,new(w,h,driftPixels)).Kind==ScrollMatchKind.Uncertain,"Horizontal drift never silently approves a broken table");
Check(ScrollQuality.FixedBands(first,Frame(37))==(0,0),"Moving body without fixed bands has no false header/footer");Console.WriteLine("V1.33 quality cases passed.");

var shortFrame=new ScrollFrame(96,32,Enumerable.Repeat((byte)220,96*32*4).ToArray());Check(ScrollQuality.FixedBands(shortFrame,shortFrame)==(0,0),"Auto fixed-band detection preserves minimum 32-pixel body");
